/**
 * The types `save/relics/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    RelicSaveState, RelicSaveRow, RelicsSaveExtract
 * depends    src/data/generated/relic-game-table.generated
 * used by    src/save/relics/index, src/save/relics/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */

// from read.ts

import type { RelicGameRarity, RelicGameUnlockType } from '../../data/generated/relic-game-table.generated'

/** The game's relic state: 0 locked, 1 mailed and waiting to be claimed, 2 unlocked. */
export type RelicSaveState = 'locked' | 'mailed' | 'unlocked'

export interface RelicSaveRow {
  index: number
  name: string | null
  label: string
  description: string | null
  /** Held by the account in any state, a mailed relic included. */
  unlocked: boolean
  /**
   * The state the save stores, or null where the save holds a plain flag or nothing for the slot.
   * Only `unlocked` adds its bonus: a mailed relic is in the save and pays nothing until claimed.
   */
  state: RelicSaveState | null
  onProfile: boolean
  /** Rare, Epic or Legendary as the game defines it; null for a slot the game table lacks. */
  rarity: RelicGameRarity | null
  /** As stored: a fraction for a percentage (0.02 is 2%), seconds for WallRebuild, metres for BotRange. */
  benefit: number | null
  /** The stat the relic adds to, by the game's name (`CoinBonus`, `LabSpeed`). */
  stat: string | null
  /** How the relic is unlocked. `Medals` is an event relic. */
  unlockType: RelicGameUnlockType | null
  /** Medals, guild tokens, wave or rank, depending on `unlockType`. */
  unlockCost: number | null
  /** The game's unlock text, e.g. "Earn 350 medals during the Rainfall event". */
  unlockDescription: string | null
  /** The event an event relic belongs to, as the unlock text names it; null when it names none. */
  event: string | null
  /** ISO date the game attaches to the relic. Later than today means it is not out yet. */
  releaseDate: string | null
}

export interface RelicsSaveExtract {
  relics: RelicSaveRow[]
  profileRelicIndices: number[]
  unlockedCount: number
  /** Relics mailed and not yet claimed. They are counted in `unlockedCount` and add no bonus. */
  mailedCount: number
  warnings: string[]
}
